import { useState } from "react";
import { Link, Navigate, useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { Eye, EyeOff, ShoppingBag, Store } from "lucide-react";
import { useAuth } from "@/context/AuthContext";
import { errMsg } from "@/lib/api";

export default function Register() {
  const { user, register } = useAuth();
  const [type, setType] = useState("buyer");
  const [form, setForm] = useState({ name: "", email: "", password: "", phone: "", store_name: "" });
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const nav = useNavigate();

  if (user && typeof user === "object") return <Navigate to="/" replace />;

  const submit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      await register({ ...form, user_type: type });
      toast.success("Conta criada");
      nav(type === "seller" ? "/seller" : "/");
    } catch (err) { toast.error(errMsg(err)); }
    finally { setLoading(false); }
  };
  const set = (k) => (e) => setForm({ ...form, [k]: e.target.value });

  return (
    <div className="mx-auto max-w-md px-6 py-10">
      <form onSubmit={submit} className="rounded-2xl border border-black/5 bg-white p-8 shadow-sm" data-testid="register-form">
        <h1 className="font-display text-2xl font-extrabold">Criar conta</h1>
        <p className="mt-1 text-sm text-ink-500">Comprar ou vender no LEAMSE Shop</p>

        <div className="mt-6 grid grid-cols-2 gap-3" data-testid="type-picker">
          <button type="button" onClick={() => setType("buyer")} data-testid="type-buyer"
                  className={`rounded-xl border p-4 text-left transition ${type === "buyer" ? "border-brand-500 bg-brand-50" : "border-black/10 hover:border-brand-500/50"}`}>
            <ShoppingBag className="h-5 w-5 text-brand-500" />
            <p className="mt-2 font-semibold">Comprador</p>
            <p className="text-xs text-ink-500">Quero comprar produtos</p>
          </button>
          <button type="button" onClick={() => setType("seller")} data-testid="type-seller"
                  className={`rounded-xl border p-4 text-left transition ${type === "seller" ? "border-brand-500 bg-brand-50" : "border-black/10 hover:border-brand-500/50"}`}>
            <Store className="h-5 w-5 text-brand-500" />
            <p className="mt-2 font-semibold">Vendedor</p>
            <p className="text-xs text-ink-500">Quero vender no shop</p>
          </button>
        </div>

        <div className="mt-6 space-y-4">
          <div>
            <label className="text-sm font-medium">Nome completo</label>
            <input required value={form.name} onChange={set("name")} data-testid="reg-name"
                   className="mt-1 h-11 w-full rounded-xl border border-black/10 bg-white px-3 text-sm outline-none focus:border-brand-500" />
          </div>
          {type === "seller" && (
            <div>
              <label className="text-sm font-medium">Nome da loja</label>
              <input required value={form.store_name} onChange={set("store_name")} data-testid="reg-store"
                     className="mt-1 h-11 w-full rounded-xl border border-black/10 bg-white px-3 text-sm outline-none focus:border-brand-500" />
            </div>
          )}
          <div>
            <label className="text-sm font-medium">E-mail</label>
            <input type="email" required value={form.email} onChange={set("email")} data-testid="reg-email"
                   className="mt-1 h-11 w-full rounded-xl border border-black/10 bg-white px-3 text-sm outline-none focus:border-brand-500" />
          </div>
          <div>
            <label className="text-sm font-medium">Telefone (opcional)</label>
            <input value={form.phone} onChange={set("phone")} data-testid="reg-phone"
                   className="mt-1 h-11 w-full rounded-xl border border-black/10 bg-white px-3 text-sm outline-none focus:border-brand-500" />
          </div>
          <div>
            <label className="text-sm font-medium">Senha</label>
            <div className="relative">
              <input type={showPass ? "text" : "password"} required minLength={6}
                     value={form.password} onChange={set("password")} data-testid="reg-password"
                     className="mt-1 h-11 w-full rounded-xl border border-black/10 bg-white px-3 pr-11 text-sm outline-none focus:border-brand-500" />
              <button type="button" onClick={() => setShowPass(!showPass)}
                      className="absolute right-0 top-0 mt-1 grid h-11 w-11 place-items-center text-ink-500"
                      data-testid="reg-toggle-pass">
                {showPass ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
              </button>
            </div>
          </div>
          <button type="submit" disabled={loading} data-testid="reg-submit"
                  className="w-full rounded-full bg-brand-500 px-6 py-3 font-semibold text-white hover:bg-brand-600">
            {loading ? "Criando…" : "Criar conta"}
          </button>
          <p className="text-center text-sm text-ink-500">
            Já tem conta? <Link to="/login" className="font-medium text-brand-600 hover:underline">Entrar</Link>
          </p>
        </div>
      </form>
    </div>
  );
}
